/* Loads this component's CSS/JS from jsDelivr, pinned to the commit hash in data-cdn-pin on the
   root div above (falls back to @main only if it is blank or still the literal "CDN_PIN"). The pin
   is found BY CLASS, deliberately NOT via document.currentScript — Bubble injects an HTML element's
   inline scripts in a way that leaves currentScript null/misattached, which silently sent every
   file to @main (cached for hours) and made data-cdn-pin look like it did nothing. */
(function(){
  /* Boot-Stub fuer den Brand-Store. Bubble ruft setUpstreemBrands() im Page-Load-Workflow, also
     regelmaessig BEVOR core.js geladen ist. Ohne diesen Stub ist window.setUpstreemBrands zu dem
     Zeitpunkt undefined, der Run-JS-Schritt wirft, und der GANZE Aufruf ist weg -- die Seite sieht
     danach aus wie eine ohne Marken, ohne dass irgendwo ein Fehler steht. core.js leert die Queue
     beim Start. Dasselbe Muster wie bei Topics und Markets (__upTopicsQueue / __upMarketsQueue). */
  window.__upBrandsQueue = window.__upBrandsQueue || [];
